package com.ledgerline.repository;
import com.ledgerline.entity.Account; import jakarta.persistence.LockModeType; import java.util.*; import org.springframework.data.jpa.repository.*; import org.springframework.data.repository.query.Param;
public interface AccountRepository extends JpaRepository<Account,Long>{List<Account> findByOwnerIdOrderByIdAsc(Long ownerId); Optional<Account> findByIdAndOwnerId(Long id,Long ownerId); @Lock(LockModeType.PESSIMISTIC_WRITE) @Query("select a from Account a where a.id=:id") Optional<Account> findLockedById(@Param("id") Long id); @Lock(LockModeType.PESSIMISTIC_WRITE) @Query("select a from Account a where a.id=:id and a.owner.id=:ownerId") Optional<Account> findLockedByIdAndOwnerId(@Param("id") Long id,@Param("ownerId") Long ownerId);}
